-- GENERATED by `wfj generate` from data/quest/quest-0003.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [3000] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "Salve, {name}. So che sei impegnat<o/a> ad aiutare la gente di Azeroth, ma quando hai tempo dovresti tornare a ⟦Ironforge=Forgiardente⟧ e parlare con uno dei paladini più rispettati della tua patria: Tiza Battleforge. È da lei che vanno i giovani paladini nanici quando è il momento di imparare di più sulla Luce e su cosa ci si aspetta da tutti noi.\n\nLa trovi al piano di sopra, nella Hall of Mysteries, che si trova nel Mystic Ward.", nil, "Ti saluto e ti do il benvenuto, {name}.", 0x85861feb, 0x04be03fc, 0x3dc4f4ac, nil, 0x35f6641b, "...m." },
  [3001] = { "In cerca di Strahad", "Trova Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "In passato ti ho insegnato delle abilità, ma è giunto il momento che sia un altro a istruirti. Si trova a ⟦Ratchet=Porto Paranco⟧ e il suo nome è Strahad. È umano, ma non lasciarti ingannare: non è debole, né è tuo nemico... almeno per ora. È potente e va rispettato. Può insegnarti evocazioni superiori, evocazioni per cui ti sento pront<o/a>. Va' da lui, ora.\n\nLo troverai a ⟦Ratchet=Porto Paranco⟧... sopra la città portuale, accanto alla torre.", nil, "Una giornata piena a ⟦Ratchet=Porto Paranco⟧, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.\n\nÈ odio quello che vedo nei tuoi occhi, {name}? Bene, lo metteremo a frutto.", 0x884bfbbe, 0x8ee66c11, 0xb6f535c4, nil, 0x44d961f5, "...m." },
  [3065] = { "⟦Simple Tablet=Tavoletta Semplice⟧", "Leggi la ⟦Simple Tablet=Tavoletta Semplice⟧ e parla con Frang nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei guerrieri Frang. Vuole parlarti quando sarai pront<o/a>. Lo troverai fuori dall'Antro del Tirocinio, al riparo all'ombra.", "<Un/Una> nuov<o/a> {race} per rinforzare i ranghi. Per me va bene.\n\nProbabilmente farai fatica a sollevare una buona arma come un'ascia, ma una lancia vale quanto qualsiasi altra cosa.\n\nBenvenut<o/a> nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Troverai questo posto adatto a te, mentre continui ad addestrarti nelle vie del {class}. Se hai domande, chiedi pure a chiunque qui intorno, e quando ti senti pront<o/a>, torna da me per l'addestramento. Padroneggio quest'arte quanto qualunque altro {class} qui nella Valle e posso trasmetterti il mio sapere... a pagamento.", 0x1de75c3d, 0x70d6f7de, 0xb9d4e50a, 0x3a60c097, 0x79d5a027, "....." },
  [3082] = { "⟦Etched Tablet=Tavoletta Intagliata⟧", "Parla con Jen'shan nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei cacciatori Jen'shan. Vuole parlarti quando sarai pront<o/a>.", "Jen'shan vede <un/una> potente <cacciatore/cacciatrice> davanti a sé, e gli spiriti approvano.\n\nLa via del cacciatore è uno dei più antichi modi di vivere della nostra gente. L'⟦Horde=Orda⟧ venne da noi quando loro faticavano solo a sopravvivere su Azeroth, e ci chiesero di insegnare, di mostrare i segreti di tante cose. Erano già forti: forti nelle vie degli sciamani; forti nelle vie dei guerrieri. Ma la via del cacciatore non era la loro via... allora.", "Ora noi insegniamo a loro quelle cose, e loro insegnano a noi altre. Diventiamo un'unica razza... quasi. Siamo alleati da tanto tempo ormai. Quindi tu ricorda di aiutarli. E Jen'shan si ricorda di aiutare te.\n\nJen'shan ti insegna le vie del cacciatore, e te le insegna bene. Non dimenticare mai che i cacciatori sono molto rispettati dalla tribù. Tu avrai un ruolo grande nel futuro... non dimenticarlo mai.\n\nQuando senti il bisogno, vieni da Jen'shan. Lei ti insegna tutto quello che può quando ti sente pront<o/a>.", 0x5f30637e, 0xd78d7114, 0x1cb5c31f, 0xd3da7216, 0xbd0588a5, "....." },
  [3083] = { "⟦Encrypted Tablet=Tavoletta Codificata⟧", "Leggi la ⟦Encrypted Tablet=Tavoletta Codificata⟧ e parla con Rwag nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei ladri Rwag. Vuole parlarti quando sarai pront<o/a>.", "Benvenut<o/a> nella ⟦Valley of Trials=Valle delle Sfide⟧, {name}. Non saresti qui se non avessi ricevuto la mia tavoletta, quindi vengo al punto.\n\nSono Rwag e mi occupo di addestrare ladri, furfanti e borseggiatori qui nella Valle. Sono io quello a cui si rivolgerà la Hand se non sarai pront<o/a> per ciò che ti aspetta. Ma non preoccuparti, la Hand non controllerà ogni tua mossa, anche se sarebbe saggio collaborare con loro, se avranno bisogno dei tuoi talenti.", "Fino ad allora, sarai sotto la mia tutela. Ti insegnerò i trucchi del mestiere, come dice qualcuno. Quando ti senti pront<o/a>, vieni da me e vedrò di addestrarti ancora. Nel frattempo, esercita le tue capacità e tienile affilate come un rasoio. Non si sa mai quando potrebbe servirti anche l'abilità più insignificante.", 0xf26f0369, 0x4028c542, 0x4649a294, 0x63ebe82c, 0x41da7694, "....." },
  [3084] = { "⟦Rune-Inscribed Tablet=Tavoletta con Rune⟧", "Parla con Shikrik nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice degli sciamani Shikrik. Vuole parlarti quando sarai pront<o/a>.", "Ah, benvenut<o/a>, {name}. Sono lieta che tu sia arrivat<o/a>. Le mie giornate sono diventate lunghe e perfino frenetiche, con tanti allievi da istruire, ma l'arrivo di uno della tua gente mi dà un grande senso di soddisfazione: ricordo i giorni in cui fui istruita da uno dei vostri sciamani.", "Come probabilmente sai, sono gli elementi a darci il nostro potere. Fuoco, terra, acqua e aria: questi sono i nostri strumenti.\n\nLa nostra forza viene dagli spiriti dei nostri antenati. Siamo le guide del nostro popolo. Come Thrall lo è per l'⟦Horde=Orda⟧, così noi lo saremo per i villaggi e le città che visitiamo. Si rivolgeranno a noi per avere saggezza e protezione. Per essere più preparat<o/a>, devi addestrarti spesso. Quando senti di aver acquisito più potere, vieni da me e ti insegnerò ciò che posso.", 0x57135a67, 0xaa674223, 0x7a1980af, 0xc763b8e8, 0x0bb859af, "....." },
  [3085] = { "⟦Hallowed Tablet=Tavoletta Benedetta⟧", "Leggi la ⟦Hallowed Tablet=Tavoletta Benedetta⟧ e parla con Ken'jai fuori dall'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei sacerdoti Ken'jai. Vuole parlarti quando sarai pront<o/a>.", "Allora ce l'hai fatta... bene, bene! Gli spiriti mi han detto che saresti venut<o/a> presto a trovare Ken'jai. Lascia che io sia uno dei primi a darti il benvenuto nella ⟦Valley of Trials=Valle delle Sfide⟧. Questo posto non sarà casa tua per molto, ma finché lo è, perché non approfittarne al meglio?", "Mentre metti alla prova te stess<o/a>, scoprirai di avere un controllo sempre migliore sugli spiriti: li chiamerai per cose sempre più grandi... ed è qui che entra in gioco il vecchio Ken'jai. Vieni a parlare col vecchio Ken'jai quando ti senti pront<o/a>. Se gli spiriti sono d'accordo, allora vediamo di insegnarti abilità più potenti... ma solo se gli spiriti sono d'accordo.\n\nOra va', parla col resto della gente della Valle. Torna a parlarmi più tardi.", 0xcbf1c524, 0xc36df6ef, 0x3e34c39a, 0x2b9a89b9, 0x5fe35355, "....." },
  [3086] = { "⟦Glyphic Tablet=Tavoletta con Glifi⟧", "Leggi la ⟦Glyphic Tablet=Tavoletta con Glifi⟧ e parla con Mai'ah vicino all'ingresso dell'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei maghi Mai'ah. Vuole parlarti quando sarai pront<o/a>.", "Già cerchi di compiacere Mai'ah, {name}. Questo è bene. Tu dai rispetto a Mai'ah, e Mai'ah forse ti ridà rispetto. Ma basta così, tu sei qui per imparare la magia, non per sentire Mai'ah che chiacchiera.\n\nC'è solo una cosa sulla magia che Mai'ah non può insegnarti, {name}, ed è come fermare la corruzione.", "Tu sei tra gli esseri più potenti del pianeta, {name}... su questo non si discute. E tutti lo sanno... lo sanno bene, pure!\n\nMa devi stare attent<o/a>! Perché non è l'orco, o l'elfo, o il nano che devi temere... sono le cose che non puoi vedere. La magia è potente. Ti fa fare cose che forse non vuoi fare. Ti fa pensare di essere più potente di quanto sei davvero. Sii paziente. Usa la testa.\n\nQuando pensi di essere pront<o/a> per l'addestramento, torna da Mai'ah. Lei ti insegna quello che sei pront<o/a> a imparare, nessun problema.", 0x2f8b4832, 0xdeaadea8, 0x57f2c952, 0x3b28c8b6, 0xc911bdb3, "....." },
  [3087] = { "⟦Etched Parchment=Cartapecora Intagliata⟧", "Leggi la ⟦Etched Parchment=Cartapecora Intagliata⟧ e parla con Jen'shan nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei cacciatori Jen'shan. Vuole parlarti quando sarai pront<o/a>.", "Ah, allora sei arrivat<o/a>, finalmente. Bene. Jen'shan ti aspettava.\n\nMolti pensano che sia una via facile, ma Jen'shan ti dice che non è vero. Dominare le bestie di Durotar e oltre richiede tanta abilità quanto dominare le arti arcane o parlare con i nostri antenati.\n\nTirare con l'arco o col fucile forse non è pericoloso per te quanto lanciare un incantesimo, ma di sicuro è pericoloso per il tuo nemico.", "Quando finiamo di parlare, dovresti parlare col resto degli abitanti della Valle. Loro ti chiedono di fare cose per loro... cose che metteranno alla prova la tua abilità e ti insegneranno alcuni dei pericoli di questa terra.\n\nMan mano che cresci in esperienza e saggezza, avrai bisogno che Jen'shan ti mostri tecniche e abilità migliori. Torna spesso da Jen'shan. Ti dirò cosa posso insegnarti.", 0x923579a2, 0x48d60d22, 0xfba32734, 0x0569874c, 0x7c765b06, "....." },
  [3088] = { "⟦Encrypted Parchment=Cartapecora Codificata⟧", "Leggi la ⟦Encrypted Parchment=Cartapecora Codificata⟧ e parla con Rwag nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei ladri Rwag. Vuole parlarti quando sarai pront<o/a>.", "Ssst, non così forte. Non mi fido di Nartok, laggiù. Chi deve nascondersi in una grotta più in fondo di me non va preso alla leggera.\n\nImmagino che tu non abbia avuto problemi a orientarti?", "Ora che sai dove mi sono rintanato, devo dirti una cosa: la Shattered Hand mi ha chiesto di tenerti d'occhio. Vogliono che ti addestri e che ti tenga informat<o/a> su qualunque cosa possa servire a loro. Anche se non ti interessa ancora aiutarli, e saresti sciocc<o/a> a non volerlo, farò il possibile per addestrarti... per un piccolo compenso. Torna da me quando pensi di essere pront<o/a>, e vedremo cosa sei pront<o/a> a imparare.", 0xccd2a2af, 0x62ff2435, 0xf5942fa0, 0x2656277a, 0xdb3c2ab9, "....." },
  [3089] = { "⟦Rune-Inscribed Parchment=Cartapecora con Rune⟧", "Leggi la ⟦Rune-Inscribed Parchment=Cartapecora con Rune⟧ e parla con Shikrik nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice degli sciamani Shikrik. Vuole parlarti quando sarai pront<o/a>.", "Allora sei arrivat<o/a>. Cominciavo a chiedermi quando ti saresti fatt<o/a> vedere. Ho mandato la cartapecora un po' di tempo fa e non ero sicura che fosse arrivata.\n\nMa basta chiacchiere... sei qui perché sei stat<o/a> scelt<o/a>, scelt<o/a> per guidare la vita spirituale del nostro popolo.", "Sarai il tramite attraverso cui comunicano i nostri antenati. Avrai il potere degli elementi ai tuoi ordini. Annientare i tuoi nemici sarà un gioco da ragazzi; guarire i tuoi alleati, facile come respirare. Tieni a mente queste cose mentre affronti nuove sfide, e torna da me tutte le volte che vuoi. Resterò qui per insegnarti nuovi incantesimi e indirizzarti sulla strada giusta quando sarai pront<o/a>.", 0xb7d19e20, 0x38687a84, 0x4edad387, 0xa3f65b21, 0xb34f759d, "....." },
  [3090] = { "⟦Tainted Parchment=Cartapecora Corrotta⟧", "Leggi la ⟦Tainted Parchment=Cartapecora Corrotta⟧ e parla con Nartok dentro l'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nDi solito, se posso, evito di avere a che fare con gli stregoni, ma credo che dovresti leggerla quando hai tempo. Se non sbaglio, viene dal tuo nuovo istruttore, Nartok. Vuole parlarti quando sarai pront<o/a>.", "Finalmente sei arrivat<o/a>... e con discrezione, per giunta. Bene.\n\nIl nostro mondo è pieno di sciocchi, {name}. Perfino il potente Thrall ha difetti più grandi di quanto i più riescano a vedere. Volta le spalle al potere necessario per rendere questa terra completamente nostra! Non siamo più il popolo che fu manipolato e usato dalle creature del Nether. Siamo un popolo a sé. Siamo fieri... e siamo forti.", "E ora anche tu sei entrat<o/a> nelle nostre file. Non fraintendermi, {name}. Solo perché hai accesso a un potere che molti invidieranno, non significa che sarai accettat<o/a> facilmente. Thrall permette a quelli come noi di entrare a Orgrimmar perché siamo ancora suoi consanguinei: non può voltarci le spalle, o diventeremmo patetici quanto gli umani che lo resero schiavo. Il punto è questo: sta' attent<o/a>. Puoi essere potente, ma se sei sciocc<o/a>, sei già mort<o/a>.\n\nSe ti serve addestramento negli incantesimi, torna da me.", 0xaf2d0c7f, 0x3d7f7224, 0x01fe275d, 0xcc951811, 0x2b34a4b3, "....." },
  [3091] = { "⟦Simple Note=Nota Semplice⟧", "Leggi la ⟦Simple Note=Nota Semplice⟧ e parla con Harutt Thunderhorn al ⟦Camp Narache=Campo Narache⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttore dei guerrieri Harutt. Se questa nota è di Harutt, non aspetterei troppo a leggerla.", "Ah, finalmente sei arrivat<o/a>, {class}. Non ho mentito nella mia nota, {name}. Anche noi siamo una stirpe speciale, non diversa dai druidi o dagli sciamani della nostra tribù. Sei altrettanto importante. Siamo noi quelli chiamati a difendere i nostri confini, a cacciare i centauri e ad andare in guerra.", "Ognuno di noi ha un ruolo nella nostra tribù. E ognuno di noi deve affrontare gli stessi riti. Non lasciare mai che il tuo orgoglio ti dica il contrario.\n\nResto qui per addestrare i nuovi guerrieri che cercano la gloria della battaglia e che seguono le vie dei nostri antenati più antichi. Quando ti senti pront<o/a>, torna da me e farò il possibile per addestrarti ancora. Va' con la benedizione della tribù, {name}.", 0x14ead102, 0x3a12e673, 0xe0460976, 0xa6b0edf0, 0xb1121bc2, "....." },
  [3092] = { "⟦Etched Note=Nota Intagliata⟧", "Leggi la ⟦Etched Note=Nota Intagliata⟧ e parla con Lanka Farshot alla ⟦Red Cloud Mesa=Mesa Nuvola Rossa⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttrice dei cacciatori Lanka. Se questa nota è di Lanka, non aspetterei troppo a leggerla.", "Benvenut<o/a> al ⟦Camp Narache=Campo Narache⟧, {name}. Sento dire buone cose su di te. La tua stirpe è forte e molti anziani ti ritengono già abile. Ma questo lo metteremo alla prova.\n\nLe pianure di Mulgore saranno la tua casa per un po': dovresti fare del tuo meglio per conoscerle molto bene. Un giorno viaggerai verso terre sconosciute per padroneggiare abilità superiori. Devi essere pront<o/a>.", "Ed è mio compito assicurarmi che tu sia pront<o/a>, insegnandoti le basi della nostra professione: come addomesticare il tuo animale, come sparare col fucile e molte altre abilità che diventeranno necessarie.\n\nI cacciatori sono una parte importante della nostra tradizione e della nostra storia, {name}. Faresti bene a ricordare quanto sei importante per la tribù. Sarai rispettat<o/a> e venerat<o/a> se servirai bene il nostro popolo.", 0x9c2dae5c, 0xed672d15, 0x78d5882a, 0x6c84c2d0, 0xbd639c75, "....." },
  [3093] = { "⟦Rune-Inscribed Note=Nota con Rune⟧", "Leggi la ⟦Rune-Inscribed Note=Nota con Rune⟧ e parla con Meela Dawnstrider al ⟦Camp Narache=Campo Narache⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttrice degli sciamani Meela. Se questa nota è di Meela, non aspetterei troppo a leggerla.", "Con la stessa rapidità con cui l'acqua cade dal cielo, eccoti davanti a me. La tua prontezza mi fa piacere. Significa che capisci l'importanza del nostro incontro e della tua presenza qui. Non sono un capo, ma comprendo gli elementi e so parlare con gli spiriti del nostro popolo. Ti insegnerò a fare lo stesso.", "Ci incontreremo molte volte nei giorni a venire. Spero che ogni volta lascerai la mia compagnia un po' più potente... un po' più preparat<o/a>. Come la Fiamma Eterna, il tuo spirito arderà luminoso e caldo.\n\nVa' ora, {name}. Va' e metti alla prova te stess<o/a>. Sarò qui per te quando ne avrai bisogno.", 0x3d99c971, 0x05a28553, 0xa97f9159, 0x8b98605c, 0xb586e860, "....." },
  [3094] = { "⟦Verdant Note=Nota Verdastra⟧", "Leggi la ⟦Verdant Note=Nota Verdastra⟧ e parla con Gart Mistrunner al ⟦Camp Narache=Campo Narache⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttore dei druidi Gart. Se questa nota è di Gart, non aspetterei troppo a leggerla.", "Sei arrivat<o/a>. Questo è bene. Gli spiriti dei nostri antenati sono diventati inquieti in tutto Mulgore e oltre, ma non so dire perché. Sarà sempre tuo dovere imparare ad ascoltare gli spiriti della natura e agire come loro avatar. Tienilo a mente.", "Anche se ci unisce un legame comune, non aspettarti una grande accoglienza dagli Elfi della Notte. Il loro orgoglio limita ancora la loro vista, ma non è affar nostro. Gli insegnamenti della Madre Terra sono tutto ciò di cui devi preoccuparti, e ti insegnerò ciò che so man mano che crescerai in saggezza.\n\nTorna spesso da me, {name}. Scoprirai che la Madre Terra concede capacità incredibili a chi le è più devoto.", 0x183c3d84, 0x92cc1324, 0x227a33b2, 0xe544de60, 0xae67cb54, "....." },
  [3095] = { "⟦Simple Scroll=Pergamena Semplice⟧", "Leggi la ⟦Simple Scroll=Pergamena Semplice⟧ e parla con Dannal Stern ad ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore dei guerrieri Dannal. Al tuo posto la leggerei prima di ripartire.", "Ah, sei arrivat<o/a>. Bene. Ho sentito che pochi altri sono riusciti a sfuggire alla \"morte\" e si stavano dirigendo in città. Forse questa tenacia ripagherà anche in futuro.\n\nPuoi ringraziare Sylvanas per la tua libertà... libertà della mente e del corpo. Anche se resti tormentat<o/a> dalla pestilenza e dai suoi effetti, ora sei liber<o/a> di andare e venire come meglio credi.", "Sarò qui per addestrarti mentre acquisti esperienza... vieni a trovarmi tutte le volte che vuoi. Chiedo un compenso minimo, ma scoprirai che tutto ciò che posso insegnarti ne vale la pena.\n\nOra va' e metti alla prova la tua abilità. Molte altre cose ti saranno rivelate man mano che acquisti esperienza, alcune delle quali non posso discutere con te qui. Sappi solo che in futuro Sylvanas avrà bisogno di guerrieri con la tua forza. Sarai la spina dorsale della nostra salvezza. Non dimenticarlo.", 0x47a42397, 0xab7828aa, 0xac9ea6e5, 0x3d4cd994, 0x26098b59, "....." },
  [3096] = { "⟦Encrypted Scroll=Pergamena Codificata⟧", "Leggi la ⟦Encrypted Scroll=Pergamena Codificata⟧ e parla con David Trias ad ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore dei ladri David Trias. Al tuo posto la leggerei prima di ripartire.", "Quindi ce l'hai fatta? Bene, col tempo avremo bisogno di altri ladri. Probabilmente gli Shadowstalkers ti troveranno quando lo riterranno opportuno, quindi non fare passi falsi e non fare niente di cui potresti pentirti. Hanno bisogno di agenti di talento... non di borseggiatori e sciocchi.", "Passo quasi tutto il tempo qui nella locanda a tenere d'occhio le facce nuove e le promesse in ascesa. Tieniti fuori dai guai e farò il possibile per insegnarti qualcosa. Torna da me quando vuoi e vedremo se sei pront<o/a> per una o due nuove abilità.", 0x1c2bcac8, 0xcefbc41c, 0x080b8339, 0x390c2af2, 0xe51c548c, "....." },
  [3097] = { "⟦Hallowed Scroll=Pergamena Benedetta⟧", "Leggi la ⟦Hallowed Scroll=Pergamena Benedetta⟧ e parla con il Chierico Oscuro Duesten nella chiesa di ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore dei sacerdoti Duesten. Al tuo posto la leggerei prima di ripartire.", "Ah, tra fuoco, pestilenza, rivolte e cose molto peggiori, un altro dei \"fedeli\" bussa alla mia porta. Be', lascia che ti dia il benvenuto, {class}. E concedimi un momento per spiegarti un paio di cose, prima che tu decida che è ora di cercare qualunque cosa ti spinga avanti: la ⟦Holy Light=Luce Sacra⟧ non ti riguarda più, gli spiriti dei tuoi antenati sono favole, e le creature del Vuoto non ti vogliono.\n\nFin qui mi segui?", "C'è solo una cosa che devi sapere: siamo sopravvissuti grazie alla sola volontà. È la fede in noi stessi che ci distingue dagli altri, e con i nostri poteri porteremo grandi cambiamenti in tutta Azeroth. I deboli verranno ad appoggiarsi a te. I lebbrosi ti chiameranno Signore. E gli ignoranti ti cercheranno per avere una guida. È mio dovere assicurarmi che tu abbia gli strumenti necessari, così che quando verrà il momento sarai pront<o/a>. Man mano che acquisti esperienza, cercami. Ti insegnerò poteri più grandi, se sarai pront<o/a>.", 0xf5ae8c7e, 0x1fc11880, 0xd59f8872, 0xe3387ae8, 0x8c4ad707, "....." },
  [3098] = { "⟦Glyphic Scroll=Pergamena con Glifi⟧", "Leggi la ⟦Glyphic Scroll=Pergamena con Glifi⟧ e parla con Isabella nella chiesa di ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttrice dei maghi Isabella. Al tuo posto la leggerei prima di ripartire.", "Sapevo che saresti venut<o/a> da me, {name}. Non perché ti manchi la volontà di seguire la tua strada, ma perché siamo spiriti affini. Entrambi abbiamo provato il dolore. Entrambi abbiamo sofferto. E ora vogliamo il potere di riprenderci ciò che sappiamo essere nostro: questa terra, le nostre vite, i nostri destini. Ma hai ancora molto da imparare.", "Devi tornare spesso da me, se vuoi diventare abbastanza potente da distruggere chi vorrebbe opporsi a noi. Le regole della magia valgono ancora per te, {name}. Scoprirai che la corruzione ti segue ancora come lupi affamati nella notte. Scoprirai che la sua carezza non è diversa da una dipendenza, una vecchia amante che vuole ancora starti accanto. Ma queste cose si possono tenere a bada. Ti controlleranno solo se glielo permetterai.\n\nOra va', e torna da me quando sarai più potente.", 0x59480f8c, 0xe2240a4b, 0x538de0b1, 0x33c31b73, 0x7b8e5ffc, "....." },
  [3099] = { "⟦Tainted Scroll=Pergamena Corrotta⟧", "Leggi la ⟦Tainted Scroll=Pergamena Corrotta⟧ e parla con Maximillion ad ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore degli stregoni Maximillion. Al tuo posto la leggerei prima di ripartire.", "Ti do il benvenuto, <fratello/sorella>. Sapevo che saresti venut<o/a>. Era solo questione di tempo.\n\nCiò che ho detto ti ha interessato, vero? Ho toccato una corda... qualcosa dentro di te sapeva che dicevo il vero. Bene.\n\nSappi però questo: non sono un traditore di Sylvanas. Semmai, lei apprezzerebbe le mie parole, visto che sono state proprio le sue convinzioni a portare i Reietti dove sono ora.", "Ho detto che uno schiavo resta uno schiavo, qualunque sia il padrone. Te lo ricordi? Sappiamo entrambi che è quel tipo di controllo, quel tipo di potere, a guidarci adesso. Cerchiamo creature che ci servano. Sappiamo di essere più potenti e di meritare più rispetto di quanto ce ne diano gli altri... e ora vogliamo prendercelo.\n\nSarò tuo alleato in questa lotta, la lotta per la nostra libertà. Libertà di scegliere le nostre alleanze. Quando ti sentirai pront<o/a>, torna da me e ti insegnerò tutto ciò che so.", 0xbb45df2a, 0x6c0ba64b, 0x7834b1d3, 0xe41ae79b, 0xde5f138f, ".....", nil, nil, nil, 0x447c5d0b, nil },
  [3100] = { "⟦Simple Letter=Lettera Semplice⟧", "Leggi la ⟦Simple Letter=Lettera Semplice⟧ e parla con Llane Beshere all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Llane, il nostro istruttore dei guerrieri. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Ah, hai ricevuto la mia lettera, {name}... bene.\n\nDi recente c'è stato un afflusso di guerrieri a Elwynn, il che è un bene per ⟦Stormwind=Roccavento⟧, ma un male per i coboldi e i Defias della zona.", "Sistemati per bene, impara a conoscere il territorio e torna da me quando ti serve addestramento. Sono qui giorno e notte.\n\nI ⟦Knights of the Silver Hand=Cavalieri della Mano d'Argento⟧ hanno fatto un buon lavoro nel rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno problemi per cui un aiuto farebbe comodo: l'aiuto che un {class} può dare loro. Buona fortuna.", 0x8a6765ad, 0xcd1a2f24, 0xfe579234, 0x76e67b55, 0x1ce50385, "....." },
  [3101] = { "⟦Consecrated Letter=Lettera Consacrata⟧", "Leggi la ⟦Consecrated Letter=Lettera Consacrata⟧ e parla con fratello Sammuel all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di fratello Sammuel, il nostro istruttore dei paladini. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Finalmente! Ci incontriamo faccia a faccia, da fratello a <fratello/sorella>. Ti do il benvenuto nella ⟦Northshire=Contea del Nord⟧. Questa sarà la tua casa per poco tempo, mentre impari come vanno le cose, ma sappi che ⟦Stormwind=Roccavento⟧ non è lontana e prima o poi il tuo cammino ti porterà lì. Fino ad allora, però, sii paziente... Cavaliere della ⟦Silver Hand=Mano d'Argento⟧.", "Nel frattempo, dovresti sapere un paio di altre cose. Per molti, in questa terra, sei un simbolo: comportati di conseguenza. La ⟦Holy Light=Luce Sacra⟧ risplende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.\n\nInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando sentirai di aver acquisito un po' di esperienza qui nella ⟦Northshire=Contea del Nord⟧, torna da me e ti insegnerò ciò che ritengo tu sia pront<o/a> a imparare. Buona fortuna... {class}!", 0x339c82f5, 0x6d6ee593, 0x26cd99ad, 0xeb1b3e11, 0x8b941ae4, ".....", nil, nil, nil, 0x808f8fbe, nil },
  [3102] = { "⟦Encrypted Letter=Lettera Codificata⟧", "Leggi la ⟦Encrypted Letter=Lettera Codificata⟧ e parla con Jorik Kerridan nella stalla dietro l'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Jorik, uno dei nostri istruttori. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Sei arrivat<o/a> qui tutt<o/a> inter<o/a>, e non sembra che ti abbiano vist<o/a> in molti. Per me va bene. Non mi piace attirare troppa attenzione, qui dietro... bello tranquillo. Sono sicuro che capisci.\n\nHai già avuto problemi? Mi fa piacere sentire di no. Le cose cambieranno presto.", "Troverai un bel po' di gruppi che bramano le nostre abilità, {name}. Avventurieri, ⟦SI:7=IR:7⟧... diamine, perfino la ⟦Defias Brotherhood=Fratellanza dei Defias⟧ non disdegnerebbe una spia o due dentro ⟦Stormwind=Roccavento⟧. Ma ricordati questo: sei <un/una> <uomo/donna> che decide da sé. Non lasciare che nessuno ti costringa a fare qualcosa che non vuoi fare! E poi, le carte buone le abbiamo noi... almeno, prima che la partita finisca. Capisci cosa intendo?\n\nComunque, volevo solo presentarmi e farti sapere che sono qui se ti serve addestramento. Passa quando vuoi.", 0x5eef0cde, 0x3d129a05, 0xb39f75e7, 0x6b9b0e24, 0xd57ec303, ".....", nil, nil, nil, nil, 0x46913652 },
  [3103] = { "⟦Hallowed Letter=Lettera Benedetta⟧", "Leggi la ⟦Hallowed Letter=Lettera Benedetta⟧ e parla con la sacerdotessa Anetta all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema della sacerdotessa Anetta, la nostra istruttrice dei sacerdoti. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Ah, finalmente sei arrivat<o/a>. Sapevo che avresti trovato la strada fino a me. La ⟦Holy Light=Luce Sacra⟧ risplende su di te e sul cammino che hai scelto. Sono tempi duri: la Legione Infuocata è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e spetta a te aiutare quante più persone possibile.", "Man mano che acquisirai esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore e lascia che la saggezza sia la tua guida. Ricorda, il mondo diventa un posto migliore solo se sei tu a renderlo tale.", 0x3871ce99, 0x3719f745, 0x63ba8573, 0x3c6b09ac, 0x69805596, "....." },
  [3104] = { "⟦Glyphic Letter=Lettera con Glifi⟧", "Leggi la ⟦Glyphic Letter=Lettera con Glifi⟧ e parla con Khelden Bremen dentro l'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Khelden, il nostro istruttore dei maghi. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Salve, {name}. Sono Khelden. Posso fare qualcosa per te?", "Ah ah, sapevo che il mio biglietto non ti avrebbe distolt<o/a> dal tuo cammino. Allora sei pront<o/a>, vero? Pront<o/a> ad accettare il tuo destino? Pront<o/a> a sfidare gli dèi e qualunque altra forza ti si pari davanti nella ricerca della conoscenza e del potere?\n\nNon mentirò, {name}: sarai temut<o/a> quanto rispettat<o/a>. Ma sappi anche questo: sarò qui per te quando avrai bisogno di addestramento. Cercami man mano che diventerai più potente.", 0x9c0b51a2, 0xb2702f67, 0xde444377, 0x1257130c, 0xea282e3b, "....." },
  [3105] = { "⟦Tainted Letter=Lettera Corrotta⟧", "Leggi la ⟦Tainted Letter=Lettera Corrotta⟧ e parla con Drusilla La Salle accanto all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Drusilla, una delle nostre istruttrici. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Ah, eccoti arrivat<o/a>, e appena in tempo, {name}. Poco fa alcune guardie erano qui e mi lanciavano occhiate curiose... patetici profani.", "Man mano che il tuo potere crescerà, sarai tentat<o/a>: devi sempre ricordarti di controllarti. Non mentirò: la corruzione può colpire chiunque pratichi l'arcano, soprattutto chi ha a che fare con le creature della ⟦Twisting Nether=Distorsione Fatua⟧. Sii paziente, e sii prudente... ma non lasciare che questo soffochi la tua ambizione.\n\nMan mano che diventerai più potente, torna da me e ti insegnerò di più sulle nostre vie.", 0xfe092140, 0xa2b9450e, 0xc0471a03, 0x04538110, 0x1fcadfe2, "....." },
  [3106] = { "⟦Simple Rune=Runa Semplice⟧", "Leggi la ⟦Simple Rune=Runa Semplice⟧ e parla con Thran Khorman nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei guerrieri Thran. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Accidenti che freddo oggi, eh? È come se la neve non se ne andasse mai, {name}.\n\nL'avrai già notato, ma ora nella nostra città vivono degli gnomi. Questo perché si sono fatti saltare fuori da casa loro. Non andarlo a dire in giro, ma non posso dargli torto: credo che anch'io sarei ricorso agli esplosivi, se ⟦Ironforge=Forgiardente⟧ fosse infestata dai Ferroscuro o roba simile.", "Altre cose che probabilmente vedrai, giusto perché tu lo sappia: nani che in combattimento usano la magia invece del fucile. Alcuni di noi che si mettono a venerare la ⟦Holy Light=Luce Sacra⟧ come certi umani e, ultimi ma non meno importanti, i trogg. Ne saprai di più più avanti, ma quello che devi sapere adesso è che io sono qui per aiutarti.\n\nSono qui per insegnarti a essere un vero {class}. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.", 0x15759692, 0xa8e2a12b, 0x0b2a8f18, 0x45cd211f, 0xc0004879, "....." },
  [3107] = { "⟦Consecrated Rune=Runa Consacrata⟧", "Leggi la ⟦Consecrated Rune=Runa Consacrata⟧ e parla con Bromos Grummner nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei paladini Bromos. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Allora ce l'hai fatta! E appena in tempo. C'è molto da fare nella ⟦Coldridge Valley=Valle Crestafredda⟧ e oltre. Avrò bisogno del tuo aiuto quanto tu avrai bisogno del mio!\n\nOra sei un Cavaliere della ⟦Silver Hand=Mano d'Argento⟧: preparati a recitare la parte.", "Gli umani ci hanno insegnato molto sulla ⟦Holy Light=Luce Sacra⟧ e su quanto il loro ordine sia importante per loro... e per la protezione di tutta Azeroth. Abbiamo grande rispetto per quanto sia radicato nella tradizione, e per come una sola figura, un solo sacrificio, possa fare la differenza tra dolore e salvezza.\n\nNoi due lavoreremo insieme per un po'. Ogni volta che pensi di essere pront<o/a>, torna da me e vedremo di farti fare un po' di addestramento. Non possiamo mandarti nel mondo impreparat<o/a>, no?", 0x605af2d1, 0x95f50fa0, 0x01726882, 0x5259d37c, 0x8df035d1, "....." },
  [3108] = { "⟦Etched Rune=Runa Intagliata⟧", "Leggi la ⟦Etched Rune=Runa Intagliata⟧ e parla con Thorgas Grimson nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei cacciatori Thorgas. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai dovuto seguire le mie tracce per trovare il posto. Ah ah!\n\nLa nostra professione è profondamente legata alla tradizione, {name}. Imparare le vie della terra. Imparare a seguire le tracce di un orso tra le montagne. Perfino sopravvivere soltanto col proprio ingegno richiede molto coraggio e astuzia. Pensi di esserne capace?", "Una cosa che devi sempre ricordare è che devi rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco; la lucentezza della tua arma; il peso delle tue munizioni; il morso di un vento gelido; tutte queste cose devi conoscerle a fondo.\n\nFarò il possibile per aiutarti, ma la maggior parte del lavoro spetta a te. Ogni volta che pensi di essere pront<o/a>, torna a parlarmi. Ti addestrerò quando posso.", 0x9cb873ec, 0xaa004bc7, 0x3f424343, 0x919eafc7, 0x04729792, "....." },
  [3109] = { "⟦Encrypted Rune=Runa Codificata⟧", "Leggi la ⟦Encrypted Rune=Runa Codificata⟧ e parla con Solm Hargrin nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei ladri Solm. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ce l'hai fatta! Ottimo!\n\nUltimamente c'è un gran fermento, quindi sono contento di contare un altro membro del clan di ⟦Ironforge=Forgiardente⟧ tra le nostre file. Troppi di noi guardano all'arcano e al divino, per i miei gusti. Niente contro di loro e le loro credenze, ma non c'è niente come una lama fredda in mano e un'ombra che ti tenga lontano dalla luce, capisci cosa intendo?", "Comunque, quando comincerai a curiosare per ⟦Coldridge=Crestafredda⟧, prima o poi probabilmente avrai bisogno di addestramento. Torna da me ogni volta che ne senti il bisogno e ti insegnerò quello che so: un trucco qui, una manovra là. Sai, la roba che ti tiene in vita e ti fa guadagnare qualche moneta in più.\n\nTieni d'occhio anche i nostri amici gnomi... gli è andata proprio male, con Gnomeregan... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.", 0xde5dc5cf, 0x5ff77ee1, 0xfc6f1297, 0xdfb79b4e, 0x81c5d183, "....." },
  [3110] = { "⟦Hallowed Rune=Runa Benedetta⟧", "Leggi la ⟦Hallowed Rune=Runa Benedetta⟧ e parla con Branstock Khalder a ⟦Anvilmar=Forgiamara⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei sacerdoti Branstock. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ah! Ce l'hai fatta, {name}! Magnifico!\n\nStavo per dire che stavo per perdere la fede che saresti arrivat<o/a>... capito, perdere la fede? È una battuta, <ragazzo/ragazza>... uff, lascia stare. Tanto non sei venut<o/a> qui per le mie battutacce.", "Sono io quello che può addestrarti mentre cominci a orientarti nella ⟦Coldridge Valley=Valle Crestafredda⟧. Quando ti senti pront<o/a>, torna da me e vedremo magari di insegnarti un incantesimo o due per difendere la valle da quei maledetti trogg.\n\nHai la Luce dalla tua parte, insieme a tutta ⟦Ironforge=Forgiardente⟧, {name}... nessuna pressione perché tu diventi qualcosa di speciale.", 0x87b91362, 0x2feef57d, 0xa512f166, 0x054b980d, 0x2b1b31d2, "....." },
  [3111] = { "Runa con Glifi", "Parla con Marryk Nurribit dentro ⟦Anvilmar=Forgiamara⟧.", "Tanto tempo fa gli alti elfi insegnarono i segreti della magia a noi e ai nostri alleati umani. Ci facevano la predica sulle regole e su come la magia possa farti impazzire! Ma non crederci. Noi non siamo come gli elfi; non abbiamo le loro stesse debolezze. Resta sulla retta via e scoprirai che la magia è tanto uno strumento potente quanto un'arma.\n\nQuando sei pront<o/a>, vieni a cercarmi dentro ⟦Anvilmar=Forgiamara⟧. Ti aspetto!", nil, nil, 0x82fc2769, 0xab749d05, 0x46703590, nil, nil, "...mm" },
  [3112] = { "⟦Simple Memorandum=Promemoria Semplice⟧", "Leggi il ⟦Simple Memorandum=Promemoria Semplice⟧ e parla con Thran Khorman nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questo promemoria da passarti. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei guerrieri Thran. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ah, be', un altro promemoria da <un/una> {race} in missione... che cosa pittoresca.\n\nNo, no, non ti sto prendendo in giro, piccol<o/a>. Bisogna rispettare la tua tenacia, questo è sicuro. Sarei altrettanto seccato se ⟦Ironforge=Forgiardente⟧ fosse stata presa dai Nani ⟦Dark Iron=Ferroscuro⟧, quindi non pensare che non capisca la tua situazione...", "Be', visto che questa è la tua direttiva principale, o come diavolo la chiamate di questi tempi, ho dato la mia parola che avrei fatto il possibile per assicurarmi che tu e i tuoi foste pronti a riprendervi la vostra casa... ed è proprio quello che farò.\n\nOgni volta che ti senti pront<o/a>, torna dal buon vecchio Thran e sarò felice di condividere con te quello che so. Addestrarti ha un costo, ma non sarà troppo caro. Buona fortuna.", 0xc08132de, 0xfd32d41c, 0xc7252d3e, 0x2813cf41, 0x954e3497, "....." },
  [3113] = { "⟦Encrypted Memorandum=Promemoria Codificato⟧", "Leggi il ⟦Encrypted Memorandum=Promemoria Codificato⟧ e parla con Solm Hargrin nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questo promemoria da passarti. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei ladri Solm. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Mi fa piacere vedere che hai ricevuto il mio biglietto e sei venut<o/a>. Scusa se ho finto che fosse un promemoria dei tuoi superiori... senza offesa. Sapevo solo che noi due, insieme ad altri come noi, dobbiamo restare uniti.\n\nNon in molti pensano che sia la cosa migliore del mondo avere la tua gente e la mia rintanate nella stessa città, ma credo che possiamo andare d'accordo benissimo. Tu che ne dici?", "Qui me ne sto per conto mio, così non ci danno la colpa per le cose che spariscono, ma se ti serve qualcosa, un po' di addestramento o roba del genere, torna pure quando vuoi.\n\nTu e io ci capiamo. Sappiamo che, alla fine dei conti, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Anche se Gnomeregan è stata... invasa, e qualunque altra cosa ci capiti, ci copriamo le spalle a vicenda. Giusto?", 0xb85fa8ab, 0xadca2176, 0xddd66e3c, 0x6c381354, 0x094ba3b2, "....." },
  [3114] = { "⟦Glyphic Memorandum=Promemoria con Glifi⟧", "Leggi il ⟦Glyphic Memorandum=Promemoria con Glifi⟧ e parla con Marryk Nurribit dentro ⟦Anvilmar=Forgiamara⟧, sopra la ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questo promemoria da passarti. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei maghi Marryk. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Sì, che c'è, {race}? Parla più forte, se non ti dispiace. Dopo qualche birra non ci sento tanto bene.", "Ah, sì! Arti Arcane... certo.\n\nEcco cosa devi sapere, {name}: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per gli incantesimi che potresti volere. E sta' alla larga da Gnomeregan, accidenti. A parte questo, buona giornata! Sarò qui se hai bisogno di me o vuoi addestrarti... o quel che è.", 0x201c49fc, 0x442b0781, 0x8ec02c25, 0x2a6a6bb4, 0xf605ca24, "....." },
  [3115] = { nil, "Leggi il Tainted Memorandum e parla con Alamar Grimm dentro ⟦Anvilmar=Forgiamara⟧, sopra la ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi aiutavi, mi hanno dato questo memorandum da passarti. Prenditi un po' di tempo per leggerlo, quando puoi. Secondo me viene da Alamar, l'istruttore degli stregoni. Dacci un'occhiata e va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.\n\nE stai attent<o/a>, {name}: quelli come te non godono di molta fiducia da 'ste parti.", "Splendido! Evidentemente hai ricevuto il mio memorandum.\n\nIgnora gli sciocchi che hai intorno, {name}. La ⟦Holy Light=Luce Sacra⟧?! La spada e lo scudo?! Non sono strade per menti aperte come le nostre. Guarda cosa ha fatto la magia \"normale\" alla nostra casa. Aggiungici quei dannati inventori, e la nostra razza è quasi scomparsa. E ora dobbiamo dipendere dai nani, che preferiscono passare il tempo ad allearsi con gli umani piuttosto che aiutarci a ricostruire la nostra casa. Siamo come cittadini di serie B. Hai visto come ci guardano?", "Ma niente di tutto questo conta. Ciò che conta è che hai visto la tua ⟦Holy Light=Luce Sacra⟧! Sai da dove viene davvero il potere. Capisci che avere alleati tutti nostri è molto più... prudente. Alleati speciali. Alleati che, qualunque sia il compito, obbediranno fino all'ultimo respiro.\n\nEd è qui che entro in gioco io, {name}. Posso insegnarti i primi rudimenti di questi poteri speciali. Vieni a trovarmi spesso e farò il possibile per insegnarti altri incantesimi.", 0x8ca3cdd0, 0xc0e37525, 0x9cf6a18f, 0xefc765ed, 0x0c6a5847, "e...." },
  [3116] = { "⟦Simple Sigil=Sigillo Semplice⟧", "Leggi il ⟦Simple Sigil=Sigillo Semplice⟧ e parla con Alyissia a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice dei guerrieri, Alyissia. Pare che Alyissia voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Ce l'hai fatta. Ne sono molto lieta.\n\nSono successe molte cose negli ultimi anni, {name}: la creazione di Teldrassil, la corruzione di molte creature della foresta, qui e altrove, la scoperta di terre che credevamo perdute come Feralas... tante cose, in così poco tempo. Ma queste sono solo alcune delle ragioni per cui siamo qui; la più importante è proteggere la nostra gente da altro male.", "Presto vedrai altri di razze diverse tra i rami della nostra casa: non lasciare che questo faccia nascere in te alcun pregiudizio. Sono i benvenuti. Ci aiuteranno quando potranno. Non tutti saranno altruisti, ma meritano un po' di fiducia.\n\nMa ora niente di tutto questo conta. Ora dobbiamo concentrarci su di te e su come puoi aiutare la nostra gente. Sono qui proprio per questo. Ti addestrerò nelle arti di <un/una> {class} man mano che diventerai più forte. Torna da me quando vuoi e farò il possibile per aiutarti.", 0x0b1c4d33, 0xd0e81f4b, 0xba14907e, 0x57568a0d, 0x95b00c23, "....." },
  [3117] = { "⟦Etched Sigil=Sigillo Intagliato⟧", "Leggi il ⟦Etched Sigil=Sigillo Intagliato⟧ e parla con Ayanna Everstride in cima ad Aldrassil, a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice dei cacciatori, Ayanna. Pare che Ayanna voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Sei arrivat<o/a>, e appena in tempo, {name}. Benvenut<o/a> a ⟦Shadowglen=Vallombra⟧.\n\nConfido che il mio sigillo ti abbia trovat<o/a> in buona salute e di buon umore?\n\nCome ti ho già detto, sono qui per addestrarti come <cacciatore/cacciatrice>: per domare le bestie che ti aiuteranno in battaglia, per usare l'arco con precisione infallibile, per rispettare le terre che chiamiamo casa e anche quelle al di là.", "Man mano che scopri ciò che ⟦Shadowglen=Vallombra⟧ ha da insegnarti, vieni a trovarmi: potrò aiutarti a capire meglio il tuo ruolo di <cacciatore/cacciatrice> e ciò di cui sei capace.\n\nSono tempi pericolosi, {name}: non dare per scontata l'abilità dei tuoi animali. In questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Va' con Elune e torna di nuovo da me.", 0x4253939a, 0xd81ae928, 0xec30768a, 0x5c32ead3, 0x1a49e722, "....." },
  [3118] = { "⟦Encrypted Sigil=Sigillo Codificato⟧", "Leggi il ⟦Encrypted Sigil=Sigillo Codificato⟧ e parla con Frahun Shadewhisper a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore dei ladri, Frahun. Pare che Frahun voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Ciao, {name}. Sono contento che tu mi abbia trovato. Pensavo che ti fossi pers<o/a> lungo la strada.\n\nNon è successo niente di nuovo a ⟦Shadowglen=Vallombra⟧ da quando ti ho mandato il mio sigillo, ma lascio a te il compito di raccogliere informazioni. Parla pure con le altre persone intorno ad Aldrassil, se vuoi.", "Fino ad allora, sappi che la nostra gente è necessaria più che mai in questi tempi incerti. La pace con le altre razze può crollare in qualsiasi momento, e si parla molto di membri dell'⟦Horde=Orda⟧ che cercano di seminare ancora più sfiducia. Ricordalo.\n\nMan mano che acquisirai potere e ti sentirai più pront<o/a>, torna qui da me e vedrò di farti addestrare. È importante che tu sappia maneggiare l'arma che preferisci, tra le altre cose.", 0xd9ec7b68, 0x0f31aa64, 0x6d5e7cd1, 0x042e42d6, 0x1de17785, "....." },
  [3119] = { "⟦Hallowed Sigil=Sigillo Benedetto⟧", "Leggi il ⟦Hallowed Sigil=Sigillo Benedetto⟧ e parla con Shanda ad Aldrassil.", "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice dei sacerdoti, Shanda. Pare che Shanda voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Mi fa piacere vedere che sei arrivat<o/a> così in fretta, {name}. Benvenut<o/a>.\n\nCome probabilmente avrai sentito, tutto Teldrassil è in fermento per l'andirivieni dei viaggiatori. Persino ad alcuni membri dell'⟦Alliance=Alleanza⟧ è stato concesso l'accesso ai rami di Teldrassil per incontrare altri Kaldorei che si preparano alle avventure che li attendono.", "Per ora non preoccuparti del mondo sotto Teldrassil. Ci sarà tempo per quello più avanti. Ora va' a parlare con gli altri a ⟦Shadowglen=Vallombra⟧: possono raccontarti meglio ciò che è accaduto. Aiutali come puoi e, ogni volta che senti di aver bisogno di altro addestramento, torna da me e ti insegnerò ciò che posso.", 0x83a52cc5, 0xf53c2a50, 0xca5600b8, 0x1f4e46af, 0x1e10f375, "....." },
  [3120] = { "⟦Verdant Sigil=Sigillo Verdastro⟧", "Leggi il ⟦Verdant Sigil=Sigillo Verdastro⟧ e parla con Mardant Strongoak, nell'albero di Aldrassil a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore dei druidi, Mardant. Pare che Mardant voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Ah, giovane {class}. Vedo che sei ansios<o/a> di proseguire i tuoi studi. Bene.\n\nMi chiedo: hai già trascorso molto tempo nel ⟦Emerald Dream=Sogno di Smeraldo⟧? Forse non sei ancora pront<o/a> per questo... Col tempo, ne sono certo.\n\nMa fino ad allora, dovremmo parlare d'altro.", "Per ora sarò il tuo mentore e la tua guida. È mio dovere insegnarti a interpretare non solo ciò che gli spiriti ci comunicano, ma anche le complessità e i segreti del ⟦Emerald Dream=Sogno di Smeraldo⟧.\n\nMan mano che imparerai e crescerai in potere, scoprirai di più sulla nostra trance del sonno. Ma fino ad allora, torna da me tutte le volte che vuoi e ti insegnerò ciò che posso sulle vie della nostra gente.", 0xbdc6d3be, 0x67426736, 0xaf299504, 0x240343bf, 0x0f1fd4af, "....." },
  [3121] = { "Una strana richiesta", "Porta il ⟦Shrunken Head=Teschio Rimpicciolito⟧ a Neeru Fireblade a Orgrimmar.", "Neeru Fireblade a Orgrimmar ha ciò che mi serve per cominciare qui! Ha preparato un intruglio che mi serve per il mio... be', vedrai.\n\nE ora fila, a Orgrimmar. Ecco, porta questo con te. È una testa rimpicciolita che ho promesso a Neeru in cambio delle erbe. È la testa di un povero nano in cui mi sono imbattuto nella foresta. Sono sicuro che Neeru ne sarà contento.\n\nTroverai Neeru nel Cleft of Shadow.", "Sì?", "Aspettavo che Uzer'i mi consegnasse questo...\n\nLascia che ti dia la miscela di erbe che ho preparato per i suoi... be', esperimenti...", 0x88b8407c, 0xaadb8829, 0x55fb2183, 0x0c07a888, 0x87bbbd29, "....." },
  [3221] = { "Parla con Renferrel", "Parla con lo speziale Renferrel alla ⟦Sepulcher=Mausolea⟧.", "Mentre eri fuori ad aiutare i nostri Inseguitori della Morte, lo speziale Renferrel ti ha mandato a chiamare. Non mi ha dato dettagli, ma voleva parlarti dei cuori di lupo che gli hai consegnato.", nil, "Ah, molto bene. C'è una questione riguardo ai cuori di lupo che mi hai portato prima che richiede la nostra attenzione.", 0x043c659a, 0x3eb5474e, 0x5ca32cb6, nil, 0x95d52ec0, "...m." },
  [3261] = { nil, "Parla con Jorn Skyseer a Camp Taurajo.", "Il tuo tempo con me è finito, {name}. Per imparare di più devi andare a Camp Taurajo, a sud, e parlare con Jorn Skyseer. Sarà lui a guidarti d'ora in poi.", nil, "Salute, giovane. Sei qui per percorrere il sentiero del cacciatore?\n\nMolto bene. Cominciamo.", 0x4d1b9bdc, 0x038243ce, 0x2e23d78b, nil, 0x88022d9d, "e..m." },
  [3281] = { "⟦Stolen Silver=Argento Rubato⟧", "Porta l'⟦Stolen Silver=Argento Rubato⟧ a Gazrog, al ⟦Crossroads=Crocevia⟧.", "Avrai anche ucciso i raptor, ma l'argento che hanno rubato va recuperato! Mi riferiscono che i raptor hanno un grande gruppo di nidi a sud di ⟦Ratchet=Porto Paranco⟧, noto come Raptor Grounds. Probabilmente hanno portato lì il nostro argento rubato.\n\nVa' in quel covo di raptor e cerca l'argento rubato. Quando lo trovi, riportamelo.", "Hai l'argento?", "Ah-ah! Allora i raptor hanno davvero nascosto l'argento nella loro tana. È difficile credere che queste bestie possano desiderare l'argento. Forse le storie sulla loro intelligenza non sono così lontane dal vero come pensavo!\n\nGrazie, {name}. Prendi questo come ricompensa per il servizio che ci hai reso, e sappi che le guardie del Crocevia devono a te la paga del mese prossimo.", 0xe35e0500, 0x12efa283, 0x2983e37d, 0xf2e4b6ca, 0x1f48ebc1, "....." },
  [3301] = { nil, "Parla con Mura Runetotem, alla ⟦Sepulcher=Mausolea⟧.", "La mia compagna di clan, Mura Runetotem, è andata a ⟦Silverpine=Pinargento⟧ per aiutare i nostri alleati non morti. ⟦Silverpine=Pinargento⟧ è una foresta malata, una foresta morente, e Mura sperava di riportarla alla vita. Forse la strana vita che si trova qui nelle ⟦Barrens=Savane⟧ può aiutarla nel suo lavoro a ⟦Silverpine=Pinargento⟧.\n\nPrendi un campione dei gusci che hai raccolto e portalo a Mura, a ⟦Silverpine=Pinargento⟧. Si trova alla ⟦Sepulcher=Mausolea⟧. Con un po' di fortuna, studiare il guscio le darà l'intuizione che le serve per guarire quel luogo morente.", "Sento su di te la polvere delle ⟦Barrens=Savane⟧, {class}. Hai viaggiato a lungo.", "Ah, che cos'è questo? Questo guscio ha un bagliore interno, come se pulsasse ancora di vita. Straordinario! Devo studiarlo più a fondo.\n\nGrazie, {name}. Con un po' di fortuna, questo guscio custodirà un segreto che potrò usare per aiutare la povera terra di ⟦Silverpine=Pinargento⟧.", 0x6ec1c3d1, 0x36a63bfc, 0xc0bed28e, 0xf5936a1e, 0x520dd133, "e...." },
  [3361] = { "Il dilemma del profugo", "Porta la ⟦Felix's Box=Scatola di Felix⟧, la ⟦Felix's Chest=Cassa di Felix⟧ e il ⟦Felix's Bucket of Bolts=Contenitore di Viti di Felix⟧ a Felix Whindlebolt, a ⟦Anvilmar=Forgiamara⟧.", "Abbiamo cacciato i trogg da Gnomeregan, ma poi è andato tutto terribilmente storto! Ora la nostra casa è completamente irradiata e noi gnomi siamo sparpagliati per tutto il Dun Morogh.\n\nNella fretta di fuggire dalle radiazioni ho perso tutti i miei effetti personali e i miei attrezzi. Sono stati i troll a prenderli. Mi hanno rubato la cassa, la scatola e il contenitore di viti! Se li sono portati nei loro accampamenti a sud-ovest di ⟦Anvilmar=Forgiamara⟧.\n\nIo non sono un avventuriero... potresti ritrovare le mie cose e portarmele qui, per favore?", "Santo cielo, {name}, questo posto non fa proprio per uno come me. Qui ci sono tante brutte creature quante ce n'erano a Gnomeregan prima dell'incidente!\n\nHai le mie cose? Se non le hai, chissà cosa ne avranno fatto i troll...", "Evviva, li hai trovati! Sei proprio la mia salvezza, amico mio. Ecco, non è molto, ma è qualcosa per il disturbo che ti ho dato! Grazie!", 0x71d49aac, 0x8c5c5442, 0x7b36eefc, 0xe6a8fff5, 0x6f038cb6, "....." },
  [3364] = { "Consegna di Scalding Mornbrew", "Porta uno Scalding Mornbrew a Durnan Furcutter, dentro ⟦Anvilmar=Forgiamara⟧, prima che si raffreddi tra cinque minuti!", "Accidenti! Dovevo portare questo delizioso Scalding Mornbrew a Durnan Furcutter, dentro ⟦Anvilmar=Forgiamara⟧, già da un pezzo, ma prima ho dovuto consegnarne uno a Grelin qui. Non arriverò mai a ⟦Anvilmar=Forgiamara⟧ prima che si raffreddi!\n\nTu sembri veloce. Forse ce la fai. Questa tazza resterà calda solo per altri cinque minuti, e Durnan non ha ordinato un mornbrew \"freddo\", quindi muoviti. ⟦Anvilmar=Forgiamara⟧ è a nord-est, un insediamento scavato nella montagna.\n\nGrazie, {name}, e non dimenticare di riportarmi il boccale!", "Sì, sono Durnan Furcutter. Hai qualcosa per me?", "Ah, bene, questo sì che ci vuole. Permettimi di fare una piccola pausa mentre mi godo questo mornbrew bollente!", 0xf0284895, 0x5506e41b, 0xbce4688b, 0x65bfe9d2, 0xd3b1def7, "....." },
  [3365] = { "Il ritorno del boccale", "Restituisci il ⟦Nori's Mug=Boccale di Nori⟧ a Nori Pridedrift.", "Ah, questo sì che ci voleva! Niente di meglio di un mornbrew caldo, anzi, BOLLENTE, in una fredda giornata d'inverno per scaldarti il fondo dell'anima.\n\nEcco qua, {name}: fammi un favore e riporta questo boccale vuoto a Nori da parte mia, eh?", "Spero che il mornbrew bollente sia arrivato a Durnan in tempo! Ti sei ricordat<o/a> di riportarmi il boccale?", "Eccellente, {name}! Non immagini quanti corrieri incontro che si dimenticano di fare una cosa semplice come riportare il boccale. I boccali non crescono sugli alberi, o almeno così mi dicono!\n\nEcco un piccolo compenso per il disturbo. Grazie ancora per l'aiuto.", 0x8db5a5c3, 0x1075f009, 0x2d2a6b06, 0x795e536d, 0x3d3438fe, "....." },
  [3366] = { "La ⟦Glowing Shard=Scheggia Brillante⟧", "Va' a ⟦Ratchet=Porto Paranco⟧ per scoprire il significato del ⟦Nightmare Shard=Frammento d'Incubo⟧.", "Il frammento è di un verde brillante e, benché solido, appena sotto la superficie sembra vorticare del fumo. Non riesci a smettere di fissare le profondità del cristallo; al tempo stesso, sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se qualcuno a ⟦Ratchet=Porto Paranco⟧ sa dirti di più su questo strano frammento.", nil, nil, 0x855951c0, 0xa0c652c0, 0xf1eddfb4, nil, nil, "...mm" },
  [3369] = { "Negli incubi", "Porta il ⟦Nightmare Shard=Frammento d'Incubo⟧ a Hamuul Runetotem, sull'⟦Elder Rise=Altura degli Anziani⟧.", "Questo frammento custodisce grandi segreti: è l'essenza pura del ⟦Emerald Dream=Sogno di Smeraldo⟧. Eppure ciò che vedo in questo frammento non è un sogno; una visione del genere si chiamerebbe piuttosto un incubo.\n\nNon voglio allarmarti, {name}, ma credo sia meglio che tu consegni questo frammento nelle mani di un saggio druido il prima possibile.\n\nÈ Hamuul Runetotem, sull'⟦Elder Rise=Altura degli Anziani⟧, che devi trovare. Va' a ⟦Thunder Bluff=Picco del Tuono⟧. Non posso dirti di più.", "Posso aiutarti in qualche modo?", "Ti ha mandato Falla? Bene, vediamo questo frammento di cui, a quanto dici, era così restia a parlare...\n\n<Hamuul scruta nel frammento>\n\nOh... non avevo... Be'.\n\n{name}, grazie per avermelo portato. Ma non è saggio parlare di cose come questa, te lo consiglio. Sono questioni di cui non dovresti occuparti.\n\nDiciamo solo che nel ⟦Emerald Dream=Sogno di Smeraldo⟧ le cose non stanno come pensavamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", 0x768d8fac, 0xe8a601a6, 0x45fe85a3, 0x42e8d794, 0xcb46c0bc, "....." },
  [3370] = { "Negli incubi", "Porta il ⟦Nightmare Shard=Frammento d'Incubo⟧ a Mathrengyl Bearwalker a Darnassus.", "Questo frammento custodisce grandi segreti: è l'essenza pura del ⟦Emerald Dream=Sogno di Smeraldo⟧. Eppure ciò che vedo in questo frammento non è un sogno; una visione del genere si chiamerebbe piuttosto un incubo.\n\nNon voglio allarmarti, {name}, ma credo sia meglio che tu consegni questo frammento nelle mani di un saggio druido il prima possibile...\n\nÈ Mathrengyl Bearwalker, del ⟦Cenarion Circle=Circolo Cenariano⟧, che devi trovare. Va' a Darnassus. Non posso dirti di più.", "Posso aiutarti in qualche modo?", "Ti ha mandato Falla? Bene, vediamo questo frammento di cui, a quanto dici, era così restia a parlare...\n\n<Mathrengyl scruta nel frammento>\n\nOh... non avevo... Be'.\n\n{name}, grazie per avermelo portato. Ma non è saggio parlare di cose come questa, te lo consiglio. Sono questioni di cui devono occuparsi soltanto i druidi cenariani.\n\nDiciamo solo che nel ⟦Emerald Dream=Sogno di Smeraldo⟧ le cose non stanno come pensavamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", 0x768d8fac, 0x92596199, 0x891baadf, 0x42e8d794, 0x1d9fadb2, "....." },
  [3376] = { "Abbattere Sharptusk!", "Porta la testa del capo Sharptusk Thornmantle al valoroso Windfeather, a ⟦Red Cloud Mesa=Mesa Nuvola Rossa⟧.", "{name}... ho sentito parlare di te, nuov<o/a> arrivat<o/a>. Forse sarai tu ad aiutarci, dove altri hanno fallito.\n\nNoi tauren ci siamo ricavati una casa in questa terra, ma non senza un prezzo. I verrospini ⟦Bristleback=Mantotergo⟧ della ⟦Brambleblade Ravine=Depressione di Rovoaguzzo⟧, guidati dal capo Sharptusk Thornmantle, ci rendono la vita difficile con la loro guerra incessante contro di noi. Ti incarico di portarmi la testa del capo!\n\nLo troverai nella gola a est, nel loro villaggio di fortuna.", "Sharptusk non ci darà più fastidio quando mi avrai portato la prova della sua morte. È la sua testa che voglio, {name}.\n\nNoi tauren viviamo per la caccia, e non c'è caccia più grande di quella contro chi è abbastanza astuto da poter dare la caccia a noi. Se riuscirai in questo compito, giovane, comincerai a capire cosa intendo.", "Oggi giustizia è stata fatta grazie alla tua prontezza, {name}. Che quest'impresa serva da monito a chiunque voglia minacciare la nostra casa.\n\nTi sei guadagnat<o/a> questa ricompensa che ti aiuterà nel tuo cammino, giovane {class}.", 0x1204c4b0, 0xa500ec30, 0x72c9ab91, 0x5068b9a6, 0x42acf4c0, "....." },
  [3513] = { "La ⟦Runed Scroll=Pergamena Runica⟧", "Porta la ⟦Runed Scroll=Pergamena Runica⟧ alla torre di guardia settentrionale nelle ⟦Barrens=Savane⟧.", "La pergamena, dall'aspetto ufficiale, è avvolta stretta da un nastro argentato. Sei <certo/certa> che a qualcuno interesserebbe vederla, ma a chi?\n\nC'è un avamposto vicino al confine con ⟦Ashenvale=Valtetra⟧, a nord: se le informazioni di questa pergamena riguardano gli Elfi della Notte, è lì che conviene portarla.", "Che c'hai?", "Bene, bene... Dove l'hai trovata?", 0x4918e4bc, 0xa4caed64, 0x97a4a11f, 0x0364734f, 0xa9e181b5, "....." },
  [3514] = { "Presenza dell'⟦Horde=Orda⟧", "Uccidi il capo dell'Eremo Grinfialunga, Rynthariel the Keymaster.", "Questa pergamena viene da quella driade intrigante, Rynthariel, custode delle chiavi dell'Eremo Grinfialunga sul ⟦Stonetalon Peak=Picco di Petrartiglio⟧.\n\nNon avrà più contatti con il messaggero a cui l'hai presa, eh, ma dobbiamo tenere la posizione qui. L'⟦Horde=Orda⟧ non tollererà le sue staffette da queste parti.\n\n{name}, va' all'Eremo Grinfialunga. Uccidi Rynthariel, e poi innalza un simbolo che tutti possano vedere. Prendi questa bandiera dell'⟦Horde=Orda⟧, {name}. Piantala nell'Eremo Grinfialunga, così non saranno tanto avventati da mandare un altro messaggero attraverso il nostro territorio.", "Non possiamo permettere all'⟦Alliance=Alleanza⟧ di stare sulla nostra terra, {name}. Fallo sapere a tutti.", "Sei <un/una> dur<o/a>! Liberare l'Eremo da Rynthariel è un grande passo, {name}. Ci metteranno molto a riorganizzarsi, e quindi possiamo contare su meno corrieri dell'⟦Alliance=Alleanza⟧ nelle ⟦Barrens=Savane⟧. Ci penseranno due volte prima di mandarne un altro da questa parte.\n\nGrazie.", 0x247781f9, 0xe57bf0f8, 0x07dbeb87, 0xc47b2c26, 0x9451d022, "....." },
  [3519] = { "Un amico in difficoltà", "Parla con Dirania Silvershine a ⟦Shadowglen=Vallombra⟧.", "Ughhh... mentre esploravo la caverna dei ragni qui vicino mi ha morso, e molto male, un ragno di nome Githyiss il Vile. Sono sicuro di essere stato avvelenato gravemente; devi aiutarmi.\n\nTi prego, avverti Dirania Silvershine. Lei potrà aiutarmi.\n\nPresto... mi gira tanto la testa...", nil, "Oh, cielo; mi chiedevo perché oggi non avessi ancora visto Iverron. E l'ho sempre avvertito di quei ragni...", 0x14600625, 0xd73f79e1, 0x6dca0a7e, nil, 0xcf23564b, "...m." },
  [3521] = { "⟦Iverron's Antidote=Antidoto di Iverron⟧", "Raccogli 7 Fungo Giacinto, 4 Moonpetal Lily e 1 ⟦Webwood Ichor=Icore di Telalegno⟧ per Dirania Silveshine a ⟦Shadowglen=Vallombra⟧.", "Forse possiamo aiutare Iverron: conosco un antidoto che dovrebbe funzionare contro il veleno. Prima di prepararlo, però, mi servono alcuni ingredienti.\n\nMi servono dei funghi giacinto. Li trovi sotto gli alberi, oppure puoi prenderli ai grell a sud di qui: sembra che ne vadano ghiotti. Mi servono anche dei gigli di lunafoglia, che crescono solo vicino agli specchi d'acqua.\n\nL'ultimo ingrediente potrebbe essere il più difficile da trovare. Raccogli l'icore di Telalegno proprio dai ragni che hanno avvelenato Iverron.", "Ti prego, raccogli gli ingredienti, {name}. Iverron ha bisogno del nostro aiuto.", "Sia ringraziata Elune, hai raccolto questi ingredienti così in fretta!\n\nTra un attimo avrò pronto l'antidoto.", 0xf8fbaf1b, 0x12503cdc, 0x32bb4179, 0xd4e56d7d, 0xbaa1ea59, "....." },
  [3522] = { "⟦Iverron's Antidote=Antidoto di Iverron⟧", "Porta l'⟦Iverron's Antidote=Antidoto di Iverron⟧ a Iverron prima che scada il tempo. Iverron si trova presso la caverna a nord.", "L'antidoto è pronto, {name}. Ti prego, fa' in modo che Iverron lo beva.\n\nC'è una cosa che devi sapere: l'antidoto resterà efficace solo per 5 minuti. Devi portarglielo in tempo.\n\nChe la rapidità sia con te, {name}.", "Oh... {name}, sono così felice che tu sia tornat<o/a>.", "Che cos'è questo, {name}?\n\nOh, lo sapevo che Dirania sarebbe riuscita ad aiutarmi!\n\n<Iverron beve l'antidoto.>\n\nMi caccio sempre nei guai e Dirania, be', riesce sempre a tirarmene fuori.\n\nMi sento molto meglio, ma credo che resterò seduto qui ancora un po', finché non mi sentirò del tutto bene. Be', per questo, e perché speravo che mi aprissi un passaggio tra quei feroci ragni Telalegno...", 0xf8fbaf1b, 0x19c81d7f, 0x9296895f, 0x4cd0a6af, 0xc1dde192, "....." },
  [3523] = { "Il Flagello dei Sotterranei", "Se accetti di aiutare Belnistrasz, parlagli di nuovo e restituiscigli la Pietra del Giuramento che ti ha dato.", "Magnifico! Mi chiamo Belnistrasz, e ti ringrazio per avermi salvato. Mi ero già dato per morto... o peggio, per pasto di questi parassiti infestati dal Flagello. Sì, ho detto proprio Flagello: hanno stretto una specie di patto con i verrospini di qui, e questo incubo ne è il risultato.\n\nAscolta... invece di fuggire e basta, voglio fare qualcosa di buono, per il bene di tutti noi. Te la senti di aiutarmi a questo scopo? Probabilmente è pericoloso, ma mi sembri il tipo che non se ne preoccupa troppo.", "Non m'interessa la politica; poco mi importa se stai con l'⟦Horde=Orda⟧ o con l'⟦Alliance=Alleanza⟧. Mi interessa di più soffocare le minacce dirette e gravi per tutte le razze... e qui dentro ne abbiamo una bella grossa.\n\nSe vuoi essere un vero eroe per tutti i popoli, consegnami la pietra del giuramento che ti ho dato come segno del tuo impegno. Io... non sono di queste parti; per la gente della mia stirpe una pietra del giuramento è importante, è il sigillo di un patto.", "Fantastico, mi sembravi proprio il tipo eroico! Ci aspetta un bel lavoro, {name}, non ti mentirò. Se restiamo concentrati sul compito, dovremmo riuscire a spuntarla.\n\nOra lascia che ti metta al corrente di quello che sta succedendo...", 0xae7d8ef9, 0x85690b77, 0x9c1e1ebf, 0x00a114d7, 0xd298f8e8, "....." },
  [3524] = { "Trascinata a riva", "Recupera le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ dalla creatura marina arenata appena a sud di Auberdine, poi portale a Gwennyth Bly'Leggonde ad Auberdine.", "Si sa che le maestose creature marine si gettano sulla costa di ⟦Darkshore=Rivafosca⟧, dove restano arenate finché non muoiono. Ultimamente queste bestie si arenano in numero sempre maggiore. Il ⟦Temple of the Moon=Tempio della Luna⟧ mi ha mandato qui a indagare, ma la presenza dei murloc lungo l'acqua ha reso difficili le mie ricerche.\n\nAppena a sud di Auberdine c'è una creatura gigantesca arenata, circondata dagli immondi murloc Greymist. Potresti andare lì e recuperare delle ossa della creatura per il nostro studio?", "Solo di recente queste creature hanno cominciato ad arenarsi sulla costa di ⟦Darkshore=Rivafosca⟧ in numero così allarmante. Non posso fare a meno di pensare che sia un cattivo presagio. Recuperare un campione delle ossa di quella creatura a sud aiuterebbe noi di Darnassus a valutare la situazione!", "Spero che i murloc non ti abbiano dato troppi problemi mentre le raccoglievi per noi! Mi assicurerò di mandarle a Darnassus con il prossimo ippogrifo. Il ⟦Temple of the Moon=Tempio della Luna⟧ mi ha dato dei fondi da distribuire a chi ci aiuta: accettane una parte, con i nostri ringraziamenti.\n\nIl tuo successo qui mi incoraggia a offrirti l'occasione di aiutare ancora il ⟦Temple of the Moon=Tempio della Luna⟧, se ti interessa...", 0x8079e34a, 0xdf94400b, 0xdd2f6ea9, 0xb30873ce, 0x899e5ad6, "....." },
  [3525] = { "Spegnere l'idolo", "Scorta Belnistrasz fino all'idolo dei verrospini nei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.\n\nProteggi Belnistrasz mentre esegue il rituale per spegnere l'idolo.", "Vicino all'ingresso c'è un idolo che fa da macabro forno per i verrospini; quelle bestie... divorano letteralmente le persone che rapiscono nelle ⟦Barrens=Savane⟧. Posso spegnere l'idolo e impedire che lo usino di nuovo, ma mi serve il tuo aiuto. Il mio piano: scortami fino all'idolo. Una volta arrivati, darò inizio al rituale. Riuscirò a stento a comunicare con te, figuriamoci a difendermi. Proteggimi mentre spengo l'idolo. Se mi abbattono, per noi è finita.\n\nSei con me?!", nil, "L'improvvisa partenza di Belnistrasz ha lasciato dietro di sé un braciere acceso. Mentre fissi la fiamma, l'immagine di un grande drago rosso dalle ampie ali ti riempie la mente. Una versione più roca della voce di Belnistrasz ti parla direttamente.\n\n\"Davvero, mortali, siete gli eroi che speravo. Grazie a voi, il massacro che queste bestie compivano appartiene al passato. La mia fiducia nei mortali come voi si è rinnovata ancora una volta. Prendi questo, una ricompensa degna di un eroe.\"", 0x17d394ac, 0xb46725ca, 0x55b0d5af, nil, 0x0f1269c0, "...m." },
  [3631] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan nelle ⟦Barrens=Savane⟧.", "Mpf. Io dico che non sei pront<o/a>, ma non spetta a me deciderlo. Strahad la pensa diversamente, e la decisione è sua... stavolta.\n\nVuole parlarti, e in fretta. Lo troverai ancora sopra ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧, nella sua piccola torre insieme ai suoi accoliti.\n\nNon perdere tempo.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0xf356d493, 0xc98053e2, nil, 0x23773eba, "...m." },
  [3681] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Scusa se interrompo i tuoi viaggi, {race}, ma ho pensato che dovessi sapere che di recente è arrivata notizia da ⟦Stormwind=Roccavento⟧: si chiede ai paladini di presentarsi lì per l'addestramento.\n\nSe non sbaglio, direi che ti stai avvicinando a un momento speciale ed è ora che cominci a studiare i Tomi.\n\nCerca Duthorian Rall a ⟦Stormwind=Roccavento⟧. Di solito addestra i paladini nella ⟦Cathedral of Light=Cattedrale della Luce⟧.", nil, "Benvenut<o/a> nella ⟦Cathedral of Light=Cattedrale della Luce⟧, {class}.", 0x85861feb, 0xfa9ae08e, 0x355bcc91, nil, 0x252bde23, "...m." },
  [3741] = { "La collana di Hilary", "Trova la collana di Hilary e riportala a Hilary, a ⟦Lakeshire=Borgolago⟧.", "La mia amica Hilary ha perso la sua collana e non riusciamo a trovarla. Abbiamo pescato qui tutto il giorno e abbiamo già cercato qui intorno. L'unica cosa che mi viene in mente è che sia caduta nel lago. I nostri genitori non vogliono che facciamo il bagno nel lago... la mia mamma dice che sott'acqua ci sono delle cose cattive, ma tu non sembri aver paura delle cose cattive.\n\nPotresti trovarla per lei, per favore?", "Ciao. Mi manca la mia collana. Me l'aveva regalata il mio papà. Papà dice che nel lago ci sono i mostri. Hai picchiato qualche mostro?", "Grazie per aver trovato la mia collana, <signor/signorina> {class}... sei tanto gentile! Ti ringrazia anche il mio gattino, vero Effsee?", 0x42188c01, 0x56803c15, 0xf3c09303, 0xe8736a32, 0x7a3fe990, ".....", nil, nil, nil, nil, 0xed8e927e },
  [3765] = { "La corruzione lontano da qui", "Raggiungi Gershala Nightwhisper ad Auberdine.", "⟦Stormwind=Roccavento⟧... un centro brulicante di attività.\n\nHo viaggiato da lontano per cercare aiuto. Si sente spesso dire che coraggiosi avventurieri girano per le strade di questa città.\n\nMio fratello, Gershala, ha bisogno di aiuto a ⟦Darkshore=Rivafosca⟧. Vive ad Auberdine, il villaggio sul mare.\n\nIl viaggio è lungo ed epico. Per questo chiedo l'aiuto di <un/una> {class} espert<o/a> come te.", nil, "Ah, quindi ti ha mandato mio fratello, Argos? Immagino che sarai stanc<o/a> per il viaggio. Ma abbiamo molto di cui parlare.", 0xba7186ed, 0xd3d2f1f5, 0x698b9ad9, nil, 0xb83a2954, "...m." },
  [3861] = { "COCCODÈ!", "Trova del ⟦Special Chicken Feed=Mangime Speciale per Polli⟧ e torna dalla gallina che hai preso in simpatia. Quando l'hai trovato, rivolgile un /cheer prima di provare a darle il ⟦Special Chicken Feed=Mangime Speciale per Polli⟧.", "«Coc... coc... coc... COCCODÈ!\n\nCoc... coc... coc.»\n\nLa gallina ti guarda e poi comincia a grattare il terreno con le zampe. Ti sembra che stia scrivendo una parola, ma non sai bene quale. Potrebbe essere... S-A-L-D-E-A-N? Prima che tu possa chiederlo, la gallina si volta e torna alle sue faccende.", "La gallina ti fissa con occhi scuri e freddi. Ti aspetta, affamata.\n\n«COCCODÈÈÈ!\n\nCoc... coc... coc.»", "«COCCODÈ!!!»\n\nLa gallina comincia a ingozzarsi del mangime che le hai messo davanti.\n\nDopo un attimo, la gallina si guarda intorno, spaventata. Si agita a disagio avanti e indietro. Che sia incinta? Forse è meglio controllare sotto di lei.", 0x15276154, 0x72531b26, 0xa6190e7e, 0x6aec8435, 0x76e1a259, "....." },
  [3901] = { "Scuotere i Rattlecage", "Uccidi 12 Rattlecage Skeleton, poi torna dal Sacerdote dell'Ombra Sarvis ad ⟦Deathknell=Albamorta⟧.", "Hai mostrato ai Reietti il tuo potenziale in circostanze normali, {name}: ora vediamo come te la cavi sotto pressione.\n\nGli scheletri Rattlecage, altri servi senza mente del Re dei Lich, sono nemici più duri degli zombi che hai affrontato finora. Ancora una volta, riduci il loro numero e dimostra il tuo valore ai Reietti. Non indugiare: quando hai finito, torna a parlarmi.", "Chi perde tempo in questo compito tanto vale che finisca a vagare senza meta come i nostri fratelli e sorelle caduti nel villaggio. Speriamo che tu te la cavi meglio di loro, eh?", "Ho finito con te, {name}: ti sei dimostrat<o/a> degn<o/a> della libertà che ti è stata data. Molti ti si opporranno per ciò che sei diventat<o/a>, ma sappi che, qualunque cosa tentino contro di noi, siamo liberi e non saremo più incatenati.\n\nPrendi questi e va' per la tua strada. Hai molto da compiere, {class}.", 0x044eea75, 0xcf755d52, 0x04a1073b, 0x9538ef09, 0x9bd22007, "....." },
  [3902] = { "Rovistare ad ⟦Deathknell=Albamorta⟧", "Cerca ad ⟦Deathknell=Albamorta⟧ e nei dintorni 6 ⟦Scavenged Goods=Beni Recuperati⟧ e portali alla Guardia della Morte Saltain.", "Ehi, tu! Se cerchi qualcosa per renderti utile, ascolta bene!\n\nCi servono reclute appena uscite dalla terra che vadano ad ⟦Deathknell=Albamorta⟧ a cercare qualsiasi tipo di equipaggiamento utile. Molto probabilmente sarà in pile di casse. Presto si risveglieranno altre reclute, e se non vogliamo che vadano in giro nude faremo meglio a metterci a rovistare!\n\nForza, al lavoro, miserabile sacco d'ossa! Non ricompenso chi non si dà da fare.", "Sei riuscit<o/a> a recuperare qualcosa di utile per noi? Non c'è vergogna nel riutilizzare ciò che altri hanno buttato via. Nessuno ci regalerà niente: noi Reietti ci arrangeremo da soli!", "Ottimo lavoro, {name}, lo sapevo che non eri un<o/a> buon<o/a> a nulla. Ecco, prendi uno degli oggetti migliori che ho trovato tra quelli raccolti finora.", 0xaae13cb4, 0x229db0af, 0x9da89248, 0x3376988f, 0xbaaab0ef, "....." },
  [3903] = { nil, "Parla con Milly Osworth.", "Ti sei dimostrato un {class} affidabile, {name}. Affidabile, e senza paura di sporcarti le mani, eh?\n\nHo un'amica, Milly Osworth, che è nei guai. È con il suo carro dall'altra parte dell'abbazia, vicino alla stalla. Sono sicuro che un paio di mani come le tue le farebbero comodo.", nil, "Oh, è stato il vicesceriffo Willem a dirti di parlare con me? È un uomo coraggioso e sempre pronto ad aiutare, ma i suoi doveri lo tengono bloccato all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧ e temo che il problema che ho oggi vada oltre le sue possibilità.\n\nForse tu puoi aiutarmi?", 0xe1f36bcd, 0xf258ab38, 0x7ad88966, nil, 0xcb7f07d4, "e..m." },
  [3904] = { "Il ⟦Milly's Harvest=Raccolto di Milly⟧", "Porta 8 casse di ⟦Milly's Harvest=Raccolto di Milly⟧ a Milly Osworth, all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Una banda di briganti, i Defias, si è stabilita nelle ⟦Northshire Vineyards=Vigne della Contea del Nord⟧ mentre facevo la vendemmia! L'ho riferito alle guardie della ⟦Northshire=Contea del Nord⟧ e mi hanno assicurato che se ne sarebbero occupate, ma... temo per il mio raccolto d'uva! Se non me la rubano i Defias, ho paura che la calpestino le nostre guardie quando inseguiranno quei delinquenti.\n\nTi prego, devi aiutarmi! Ho raccolto quasi tutta l'uva nei secchi, ma li ho lasciati nelle vigne a sud-est.\n\nPortami quelle casse! Salva il mio raccolto!", "Hai il mio raccolto, {name}?", "Oh, grazie, {name}! Hai salvato il mio raccolto! E spero che tu abbia fatto capire a qualcuno di quei Defias che qui non possono combinare guai.\n\nDi questi tempi avremo anche poche guardie, ma siamo fortunati ad avere eroi come te a proteggerci!", 0xb7c26a3d, 0x92647f37, 0x0fa99512, 0x44af6d31, 0xbc754155, "....." },
  [3905] = { "⟦Grape Manifest=Bollettino dell'Uva⟧", "Porta il ⟦Grape Manifest=Bollettino dell'Uva⟧ a fratello Neals, nell'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Ora che il mio raccolto è salvo, porta questo ⟦Grape Manifest=Bollettino dell'Uva⟧ a fratello Neals. Gestisce le scorte di cibo e bevande della ⟦Northshire=Contea del Nord⟧, e sono sicura che sarà felicissimo di sapere che ha uva fresca.\n\nTroverai fratello Neals nell'abbazia, sul campanile... dove gli piace assaggiare il suo vino.", "Sembri di ottimo umore! Vieni! Siediti e bevi qualcosa!", "Vediamo un po'...\n\nOh, cielo! L'uva di Milly è salva! Quando mi ha detto che dei briganti avevano invaso le sue vigne ho quasi perso la speranza, ma la mia fede nella Luce non ha vacillato!\n\nE grazie al tuo coraggio ora abbiamo uva per altro vino! Che la Luce ti benedica, {name}, e ti protegga!", 0x46e6ddee, 0x54a8efd7, 0x7e4adc7b, 0x920c46b4, 0x8ad49c5d, "....." },
  [3921] = { nil, "Porta il ⟦Broken Samophlange=Samoflago Rotto⟧ a Wenikee Boltbucket.", "Credo di aver rotto quel samoflago. Non va bene, perché ne ho già parlato con alcuni colleghi di Undermine ed erano molto incuriositi. Dobbiamo trovare un modo per aggiustarlo!\n\nPorta il samoflago rotto a Wenikee Boltbucket, appena a sud di Mor'shan Rampart, l'avamposto dell'Orda tra le ⟦Barrens=Savane⟧ e ⟦Ashenvale=Valtetra⟧. È molto sveglia e curiosa. Scommetto che, se le mostri il samoflago, coglierà al volo l'occasione di ripararlo.", "Sono molto impegnata con il mio lavoro, {class}. A meno che tu non abbia qualcosa per me, sarebbe meglio che te ne andassi...", "Oh, e questo cos'è? Un samoflago, dici? E che cos'è un samoflago??\n\nAh... ma guarda come si muove quando lo maneggi. E dentro si sente il rumore di ingranaggi complicati. Oh, accidenti! Voglio ripararlo e vedere cosa fa, tu no??", 0x60e1e274, 0x7bdd885e, 0x53dfcdc8, 0xa50b6b78, 0xec4e6f32, "e...." },
  [3922] = { nil, "Porta 15 Cuscinetto a Wenikee Boltbucket, nelle ⟦Barrens=Savane⟧.", "Voglio riparare questo samophlange, ma per farlo mi servono un po' di materiali. Ho finito i nugget slug calibro diciassette virgola cinque e me ne serviranno un bel po' per il lavoro che mi aspetta.\n\nIl posto più vicino dove trovarli è la ⟦Sludge Fen=Palude Fangosa⟧, a est. La ⟦Venture Company=S.P.R. & Co.⟧ di solito li tiene nei secchi degli attrezzi. Va' alla ⟦Sludge Fen=Palude Fangosa⟧ e guarda nei secchi degli attrezzi che trovi lì, poi torna da me quando avrai raccolto abbastanza nugget slug.", "Hai i nugget slug, {name}? Sto tenendo d'occhio questo samophlange e non vedo l'ora di metterci le mani.", "Grande, li hai presi! Ora posso mettermi al lavoro...", 0x048fd5a7, 0x60a82d68, 0x9253461d, 0xaa34b2e5, 0x1136f9bf, "e...." },
  [3923] = { nil, "Porta il ⟦Broken and Battered Samophlange=Samoflago Rotto e Danneggiato⟧ a Rilli Greasygob, a Orgrimmar.", "Be', non ha funzionato. Ho messo qualche indicatore in più sul samoflago per misurarne l'integrità strutturale, e segnano l'integrità al minimo storico. Potrei aggiungere altri quadranti e magari una leva o due per provare a ripararlo, ma... credo che peggiorerei solo le cose.\n\nDovresti portare il samoflago a Rilli Greasygob. Lavorava per la ⟦Venture Company=S.P.R. & Co.⟧: se qualcuno sa come ripararlo, è Rilli.\n\nLo trovi al Nogg's Machine Shop di Orgrimmar, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "Attent<o/a> alla testa! Non voglio che mi intralci il lavoro!", "Cos'è questo? Ma è un samoflago! Dove l'hai preso? Sei andat<o/a> a ficcare il naso nei possedimenti della ⟦Venture Company=S.P.R. & Co.⟧ nelle ⟦Barrens=Savane⟧?\n\nDevi essere molto coraggios<o/a>, o molto stupid<o/a>.", 0x4f8af447, 0x451916dc, 0xf87c0604, 0xe6681672, 0xdb24502b, "e...." },
  [3924] = { "⟦Samophlange Manual=Manuale per Samoflago⟧", "Porta il ⟦Samophlange Manual=Manuale per Samoflago⟧ a Rilli Greasygob, a Orgrimmar.", "Credo di poter riparare il samoflago, ma prima mi serve il manuale d'uso. Quando lavoravo per la ⟦Venture Company=S.P.R. & Co.⟧ avevo un rivale, il capo Copperplug, che custodiva gelosamente i segreti del samoflago e ne rivelava solo qualche briciola a chi godeva della sua fiducia. Io non ero tra quei pochi fortunati...\n\nIl capo Copperplug stava alla ⟦Boulder Lode Mine=Miniera di Pietravera⟧, nelle ⟦Barrens=Savane⟧ nord-orientali. Prendigli il manuale, e se ne ha dato qualche pagina a qualcuno, dovrai recuperare anche quelle.", "Hai il manuale?", "Hai preso il manuale! Non vedo l'ora di leggerlo e scoprire come riparare il samoflago! Ho parlato con Sputtervalve a ⟦Ratchet=Porto Paranco⟧: voleva ringraziarti per l'aiuto e ricompensare i tuoi sforzi.\n\nAnch'io voglio ringraziarti, e se mai riuscirò a riparare questo affare te lo farò sapere...", 0x414249b4, 0x7dc1529a, 0xbe65b209, 0xfd8a38a1, 0xd5013a6b, "....." },
})
